local function addMossSkin(script, shell, rust)
    local vs = getScriptManager():getVehicle(script)
    if not vs then return end
    local short = script:gsub("^%a+%.", "")
    vs:Load(short, "{ skin { texture = " .. shell .. ", textureRust = " .. rust .. ", } }")
end
